function Test-LeapYear {
    <#
    .SYNOPSIS
    Given a year, report if it is a leap year.
    #>
    [CmdletBinding()]
    Param(
        [int]$Year
    )

    # A year is a leap year if it divides by 4, except for centuries that don't divide by 400.
    return (Test-DivisibleBy $Year 4) -and (-not (Test-DivisibleBy $Year 100) -or (Test-DivisibleBy $Year 400))
}

function Test-DivisibleBy([int]$Year, [int]$Divisor) {
    $Year % $Divisor -eq 0
}

